    { id: "wayfinding-east", x: 6, z: 6, radius: 1.7 },
    { id: "featured-showcase", x: expanded ? liftLayout.showcase.x : -7, z: expanded ? liftLayout.showcase.z + 0.9 : 3.1, radius: 1.3 }
